import sys

def main():
    s = sys.stdin.read().split()[0]
    stack = []
    best = 0
    res = []
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        elif ch == ')':
            d = len(stack)
            a = stack.pop()
            if d > best:
                best = d
                res = []
            if d == best:
                res.append((a, i))
    res.sort()
    out = [str(len(res))]
    for a, b in res:
        out.append('%d %d' % (a, b))
    print('\n'.join(out))

