    if s[i] == '(':
        cnt = 0
        for j in range(i, n):
            if s[j] == '(':
                cnt += 1
            elif s[j] == ')':
                cnt -= 1
            if cnt == 0:
                pairs.append((i, j))
                break
depths = []
for (a, b) in pairs:
    depths.append(1 + sum(1 for (c, e) in pairs if c < a and b < e))
m = max(depths) if depths else 0
sel = [p for p, d in zip(pairs, depths) if d == m] if pairs else []
print(len(sel))
for a, b in sel:
    print(a, b)

